#include <stdio.h>
#include <math.h>
#include <omp.h>

static long num_steps = 10000000;

int main() {
    double step = 1.0 / (double)num_steps;
    double sum = 0.0;

    double t0 = omp_get_wtime();

    #pragma omp parallel for reduction(+:sum)
    for (long i = 0; i < num_steps; i++) {
        double x = (i + 0.5) * step;
        sum += 4.0 / (1.0 + x * x);
    }

    double pi = step * sum;
    double t1 = omp_get_wtime();

    printf("Computed Pi = %.10f (Error = %.10f)\n", pi, fabs(pi - 3.141592653589793));
    printf("Execution Time = %f seconds\n", t1 - t0);
    return 0;
}

#include <stdio.h>
#include <omp.h>

int is_prime(int n) {
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int main() {
    int count = 0;
    int sum = 0;

    // Parallel loop over all odd candidate pairs
    #pragma omp parallel for schedule(dynamic) reduction(+:count) reduction(+:sum)
    for (int p = 3; p < 198; p += 2) {
        if (is_prime(p) && is_prime(p + 2)) {
            count++;
            sum += (p + (p + 2));
        }
    }

    printf("Twin prime pairs < 200: %d\n", count);
    printf("Sum of all twin primes < 200: %d\n", sum);
    return 0;
}

#include <stdio.h>
#include <omp.h>

#define N 3

int main() {
    // Augmented matrix [A | b]
    double A[N][N + 1] = {
        {1.0, -1.0, 1.0,  4.0},
        {1.0, -4.0, 2.0,  8.0},
        {1.0,  2.0, 8.0, 12.0}
    };

    double t0 = omp_get_wtime();

    // Gaussian Elimination Phase
    for (int k = 0; k < N - 1; k++) {
        #pragma omp parallel for
        for (int i = k + 1; i < N; i++) {
            double factor = A[i][k] / A[k][k];
            for (int j = k; j <= N; j++) {
                A[i][j] -= factor * A[k][j];
            }
        }
    }

    // Backward Substitution Phase (Sequential)
    double x[N];
    for (int i = N - 1; i >= 0; i--) {
        x[i] = A[i][N];
        for (int j = i + 1; j < N; j++) {
            x[i] -= A[i][j] * x[j];
        }
        x[i] = x[i] / A[i][i];
    }

    double t1 = omp_get_wtime();

    printf("Solution vector:\n");
    printf("x = %f (5/3 = %.6f)\n", x[0], 5.0 / 3.0);
    printf("y = %f (-5/6 = %.6f)\n", x[1], -5.0 / 6.0);
    printf("z = %f (3/2 = %.6f)\n", x[2], 3.0 / 2.0);
    printf("Elapsed Time = %f seconds\n", t1 - t0);

    return 0;
}
